using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using GrampsWeb.Mcp.Config;
using GrampsWeb.Mcp.Exceptions;
using GrampsWeb.Mcp.Models;
using GrampsWeb.Mcp.Serialization;
using Microsoft.Extensions.Logging;

namespace GrampsWeb.Mcp.Client;

/// <summary>
/// HTTP client for Gramps Web API with JWT authentication and automatic token refresh.
/// </summary>
public class GrampsApiClient
{
    private static readonly string[] SensitiveFieldNames =
    [
        "password", "token", "access", "refresh", "authorization"
    ];

    private readonly HttpClient _httpClient;
    private readonly GrampsConfig _config;
    private readonly ILogger<GrampsApiClient> _logger;
    private readonly GrampsAuthTokenProvider _tokenProvider;
    private readonly MutationGate _mutationGate;
    private readonly GrampsTypeVocabularies _typeVocabularies;
    private string? _accessToken;

    /// <summary>
    /// Timeout for HTTP requests (30 seconds).
    /// </summary>
    private static readonly TimeSpan RequestTimeout = TimeSpan.FromSeconds(30);

    public GrampsApiClient(
        HttpClient httpClient,
        GrampsConfig config,
        ILogger<GrampsApiClient> logger,
        GrampsAuthTokenProvider tokenProvider,
        MutationGate? mutationGate = null,
        GrampsTypeVocabularies? typeVocabularies = null)
    {
        _httpClient = httpClient ?? throw new ArgumentNullException(nameof(httpClient));
        _config = config ?? throw new ArgumentNullException(nameof(config));
        _logger = logger ?? throw new ArgumentNullException(nameof(logger));
        _tokenProvider = tokenProvider ?? throw new ArgumentNullException(nameof(tokenProvider));
        _mutationGate = mutationGate ?? MutationGate.Disabled;
        _typeVocabularies = typeVocabularies ?? new GrampsTypeVocabularies();

        // Set base address without /api suffix; it's added per endpoint
        _httpClient.BaseAddress = new Uri(_config.ApiUrl);
        _httpClient.Timeout = RequestTimeout;
    }

    /// <summary>
    /// Stable key for caches scoped to this client's API URL and configured tree.
    /// </summary>
    public string CacheScopeKey => HandleCache.BuildScopeKey(_config.ApiUrl, _config.TreeId);

    public Task<IDisposable> BeginUpdateAsync() => _mutationGate.BeginUpdateAsync();

    /// <summary>
    /// Gets a new JWT access token: POST /api/token/ with the username and password in a JSON body,
    /// or POST /api/token/refresh/ with the configured refresh token.
    /// </summary>
    public async Task GetTokenAsync()
    {
        _accessToken = await _tokenProvider.GetTokenAsync();
    }

    /// <summary>
    /// Refreshes the JWT access token via POST /api/token/refresh/.
    /// </summary>
    public async Task RefreshTokenAsync()
    {
        _accessToken = await _tokenProvider.RefreshTokenAsync();
    }

    /// <summary>
    /// Ensures the client is authenticated. Obtains a new token or refreshes if needed.
    /// Refreshes if token expires in less than 2 minutes.
    /// </summary>
    public async Task EnsureAuthenticatedAsync()
    {
        _accessToken = await _tokenProvider.GetAccessTokenAsync();
    }

    /// <summary>
    /// Performs a GET request and deserializes the response to T.
    /// Adds Authorization header and executes request.
    /// </summary>
    public async Task<T> GetAsync<T>(string path)
    {
        var body = await GrampsReadScope.ReadAsync(this, path, () => GetJsonBodyAsync(path));
        return Deserialize<T>(body);
    }

    /// <summary>
    /// GET <c>/api/types/default/{category}</c>, or every category when it is empty.
    /// Kept for the process lifetime by <see cref="GrampsTypeVocabularies"/>.
    /// </summary>
    public async Task<JsonElement> GetDefaultTypesAsync(string category = "")
    {
        var path = $"/api/types/default/{category}";
        return Deserialize<JsonElement>(
            await _typeVocabularies.GetDefaultAsync(path, () => GetJsonBodyAsync(path)));
    }

    /// <summary>
    /// GET <c>/api/types/custom/</c>, kept for <see cref="GrampsTypeVocabularies.CustomTypesTtl"/>;
    /// <paramref name="reload"/> reads it again.
    /// </summary>
    public async Task<JsonElement> GetCustomTypesAsync(bool reload = false) =>
        Deserialize<JsonElement>(
            await _typeVocabularies.GetCustomAsync(() => GetJsonBodyAsync("/api/types/custom/"), reload));

    // Cache wire JSON, not mutable DTOs: each caller receives its own object graph.
    private static T Deserialize<T>(string body) =>
        JsonSerializer.Deserialize<T>(body, GrampsJson.Options)
            ?? throw new InvalidOperationException($"Failed to deserialize response as {typeof(T).Name}");

    private async Task<string> GetJsonBodyAsync(string path)
    {
        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Get, path), request => SendWithLoggingAsync(request));
            var body = await response.Content.ReadAsStringAsync();

            if (!response.IsSuccessStatusCode)
            {
                throw new GrampsApiException(response.StatusCode, body);
            }

            return body;
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// GET for list endpoints that may return either a JSON array or a paged <c>{ objects, total, page }</c> object.
    /// </summary>
    public async Task<GrampsPagedResult<T>> GetPagedListAsync<T>(string path) where T : class
    {
        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Get, path), request => SendWithLoggingAsync(request));
            var body = await response.Content.ReadAsStringAsync();

            if (!response.IsSuccessStatusCode)
                throw new GrampsApiException(response.StatusCode, body);

            var parsed = GrampsPagedResultParser.Parse<T>(body, GrampsJson.Options)
                ?? new GrampsPagedResult<T> { Objects = Array.Empty<T>(), Total = 0, Page = 1 };

            // Array-shaped responses do not reliably include total/page metadata.
            // Prefer explicit headers when present; otherwise mark total unknown (-1) instead of guessing.
            using (var doc = JsonDocument.Parse(body))
            {
                if (doc.RootElement.ValueKind == JsonValueKind.Array)
                {
                    parsed.Page = GetIntQuery(path, "page") ?? parsed.Page;
                    parsed.Total = TryGetTotalFromHeaders(response.Headers, response.Content.Headers) ?? -1;
                }
            }

            return parsed;
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// Performs a binary GET request without logging or converting the response body as text.
    /// </summary>
    public async Task<GrampsBinaryResponse> GetBytesAsync(string path, long maxBytes)
    {
        if (maxBytes <= 0)
            throw new ArgumentOutOfRangeException(nameof(maxBytes), "Maximum byte count must be positive.");

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Get, path), SendBinaryWithLoggingAsync);

            if (!response.IsSuccessStatusCode)
            {
                var errorBody = await response.Content.ReadAsStringAsync();
                throw new GrampsApiException(response.StatusCode, errorBody);
            }

            var contentLength = response.Content.Headers.ContentLength;
            if (contentLength.HasValue && contentLength.Value > maxBytes)
                throw MediaSizeLimitExceeded(contentLength.Value, maxBytes);

            var bytes = await ReadBytesWithLimitAsync(response.Content, maxBytes);
            var mimeType = response.Content.Headers.ContentType?.MediaType;
            return new GrampsBinaryResponse(bytes, mimeType);
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// POST to create an object. Returns the <c>handle</c> and <c>gramps_id</c> extracted from the
    /// Gramps mutation-array response (<c>[{"_class":"X","new":{...}}]</c>) or bare entity JSON.
    /// Either value may be null if the API response format is unexpected — callers should treat that
    /// as "created successfully but handle unknown".
    /// </summary>
    public async Task<(string? Handle, string? GrampsId)> PostMutationAsync(
        string path, object body, string grampsClass)
    {
        EnsureWritable();
        var json = JsonSerializer.Serialize(body, GrampsJson.Options);

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Post, path) { Content = JsonContent(json) },
                SendMutationAsync);
            var responseBody = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, responseBody);

            return GrampsMutationParser.ExtractHandleAndId(responseBody, grampsClass);
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// POST <c>/api/objects/</c>: adds every object of <paramref name="objects"/> in one database transaction,
    /// all or none, in the order given. Returns the response body, the transaction's changes
    /// (<c>[{"_class","handle","type","old","new"}]</c>), which also list the people a new family updated.
    /// </summary>
    public async Task<string> PostObjectsAsync(JsonArray objects)
    {
        EnsureWritable();
        var json = objects.ToJsonString();

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Post, "/api/objects/") { Content = JsonContent(json) },
                SendMutationAsync);
            var responseBody = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, responseBody);
            return responseBody;
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// PUT to update an object. Throws <see cref="GrampsApiException"/> on any non-success status;
    /// on success returns without parsing the response body.
    /// </summary>
    public async Task PutMutationAsync(string path, object body)
    {
        EnsureWritable();
        var json = JsonSerializer.Serialize(body, GrampsJson.UpdateOptions);

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Put, path) { Content = JsonContent(json) },
                SendMutationAsync);
            var responseBody = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, responseBody);
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// POST <c>/api/media/</c> with a file as the request body. Gramps Web stores the file under its MD5
    /// checksum and creates a media record with that checksum, path and MIME type and an empty description.
    /// Returns the new record's handle and Gramps ID, either of which may be null as for
    /// <see cref="PostMutationAsync"/>.
    /// </summary>
    public async Task<(string? Handle, string? GrampsId)> PostMediaFileAsync(byte[] bytes, string mimeType)
    {
        EnsureWritable();

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Post, "/api/media/") { Content = FileContent(bytes, mimeType) },
                SendUploadMutationAsync);
            var responseBody = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, responseBody);

            return GrampsMutationParser.ExtractHandleAndId(responseBody, "Media");
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// PUT <c>/api/media/{handle}/file</c>: replaces the file of an existing media record, which then takes
    /// the new file's checksum, path and MIME type. Returns false when Gramps Web answers 409 because the
    /// record already holds an identical file.
    /// </summary>
    public async Task<bool> PutMediaFileAsync(string handle, byte[] bytes, string mimeType)
    {
        EnsureWritable();
        var path = $"/api/media/{Uri.EscapeDataString(handle)}/file";

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Put, path) { Content = FileContent(bytes, mimeType) },
                SendUploadMutationAsync);
            if (response.StatusCode == System.Net.HttpStatusCode.Conflict)
                return false;
            var responseBody = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, responseBody);
            return true;
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// Performs a DELETE request.
    /// Adds Authorization header and executes request.
    /// </summary>
    public async Task DeleteAsync(string path)
    {
        EnsureWritable();

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Delete, path), SendMutationAsync);
            var body = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, body);
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// POST without a body to an action endpoint such as <c>/api/transactions/history/{id}/undo</c>.
    /// Returns the status and body of a successful reply, e.g. 202 with a task reference when Gramps Web
    /// runs the action in the background; throws <see cref="GrampsApiException"/> on any other status.
    /// </summary>
    public async Task<(System.Net.HttpStatusCode StatusCode, string Body)> PostActionAsync(string path)
    {
        EnsureWritable();

        try
        {
            using var response = await SendAuthorizedAsync(
                () => new HttpRequestMessage(HttpMethod.Post, path), SendMutationAsync);
            var body = await response.Content.ReadAsStringAsync();
            ThrowIfMutationFailed(response, body);
            return (response.StatusCode, body);
        }
        catch (HttpRequestException ex)
        {
            throw new GrampsApiException(System.Net.HttpStatusCode.BadGateway, ex.Message);
        }
    }

    /// <summary>
    /// Sends a request built by <paramref name="createRequest"/> with the cached access token. When the
    /// API rejects the token, e.g. after the server's SECRET_KEY changed, replaces it and sends a new
    /// request once; see <see cref="GrampsAuthTokenProvider.IsRejectedAccessTokenAsync"/>.
    /// </summary>
    private async Task<HttpResponseMessage> SendAuthorizedAsync(
        Func<HttpRequestMessage> createRequest,
        Func<HttpRequestMessage, Task<HttpResponseMessage>> send)
    {
        await EnsureAuthenticatedAsync();
        var token = _accessToken!;
        var response = await send(WithBearer(createRequest(), token));
        if (!await GrampsAuthTokenProvider.IsRejectedAccessTokenAsync(response))
            return response;

        _logger.LogWarning(
            "Gramps API rejected the access token with {StatusCode}; re-authenticating and retrying once",
            (int)response.StatusCode);
        response.Dispose();
        token = await _tokenProvider.ReplaceRejectedAccessTokenAsync(token);
        _accessToken = token;
        return await send(WithBearer(createRequest(), token));
    }

    private static HttpRequestMessage WithBearer(HttpRequestMessage request, string accessToken)
    {
        request.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", accessToken);
        return request;
    }

    private static StringContent JsonContent(string json) => new(json, Encoding.UTF8, "application/json");

    private static ByteArrayContent FileContent(byte[] bytes, string mimeType)
    {
        var content = new ByteArrayContent(bytes);
        content.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue(mimeType);
        return content;
    }

    /// <summary>Throws when the server runs read-only; every mutation calls it before sending.</summary>
    public void EnsureWritable()
    {
        if (_config.ReadOnly)
            throw new InvalidOperationException(
                "Read-only mode is enabled; create, update, and delete tools are disabled.");
    }

    private Task<HttpResponseMessage> SendMutationAsync(HttpRequestMessage request) =>
        _mutationGate.RunAsync(() => SendWithLoggingAsync(request));

    private Task<HttpResponseMessage> SendUploadMutationAsync(HttpRequestMessage request) =>
        _mutationGate.RunAsync(() => SendUploadWithLoggingAsync(request));

    private static void ThrowIfMutationFailed(HttpResponseMessage response, string body)
    {
        if (!response.IsSuccessStatusCode)
            throw GrampsApiException.FromMutationResponse(response, body);
    }

    private async Task<HttpResponseMessage> SendWithLoggingAsync(
        HttpMethod method,
        string path,
        HttpContent? content = null,
        bool skipRequestBodyLogging = false)
    {
        var request = new HttpRequestMessage(method, path) { Content = content };
        return await SendWithLoggingAsync(request, skipRequestBodyLogging);
    }

    /// <summary>
    /// Information logs carry only method, path, status, timing and body length: bodies and
    /// query strings hold genealogy data (names, dates, search terms). Debug adds them.
    /// </summary>
    private async Task<HttpResponseMessage> SendWithLoggingAsync(
        HttpRequestMessage request,
        bool skipRequestBodyLogging = false)
    {
        var requestBody = request.Content is null
            ? null
            : await request.Content.ReadAsStringAsync();

        _logger.LogInformation(
            "Gramps API request: {Method} {Path} BodyLength={BodyLength}",
            request.Method.Method,
            PathForLog(request.RequestUri),
            requestBody?.Length ?? 0);

        if (_logger.IsEnabled(LogLevel.Debug))
        {
            _logger.LogDebug(
                "Gramps API request body: {Method} {Url} Body={RequestBody}",
                request.Method.Method,
                request.RequestUri?.ToString() ?? string.Empty,
                skipRequestBodyLogging ? "<redacted>" : SanitizeAndLimitForLog(requestBody) ?? "<empty>");
        }

        return await SendAndBufferResponseAsync(request);
    }

    /// <summary>
    /// Like <see cref="SendWithLoggingAsync(HttpRequestMessage, bool)"/> for a request whose body is a file:
    /// logs its MIME type and length, never the bytes.
    /// </summary>
    private async Task<HttpResponseMessage> SendUploadWithLoggingAsync(HttpRequestMessage request)
    {
        _logger.LogInformation(
            "Gramps API upload: {Method} {Path} ContentType={ContentType} BodyLength={BodyLength}",
            request.Method.Method,
            PathForLog(request.RequestUri),
            request.Content?.Headers.ContentType?.MediaType ?? "<none>",
            request.Content?.Headers.ContentLength ?? 0);

        return await SendAndBufferResponseAsync(request);
    }

    /// <summary>Sends the request, logs the response and buffers its body as text for the caller.</summary>
    private async Task<HttpResponseMessage> SendAndBufferResponseAsync(HttpRequestMessage request)
    {
        var startedAt = DateTime.UtcNow;
        var response = await _httpClient.SendAsync(request);
        var elapsedMs = (DateTime.UtcNow - startedAt).TotalMilliseconds;
        var responseBody = await response.Content.ReadAsStringAsync();

        _logger.LogInformation(
            "Gramps API response: {Method} {Path} Status={StatusCode} DurationMs={DurationMs} BodyLength={BodyLength}",
            request.Method.Method,
            PathForLog(request.RequestUri),
            (int)response.StatusCode,
            elapsedMs,
            responseBody.Length);

        if (_logger.IsEnabled(LogLevel.Debug))
        {
            _logger.LogDebug(
                "Gramps API response body: {Method} {Url} Body={ResponseBody}",
                request.Method.Method,
                request.RequestUri?.ToString() ?? string.Empty,
                SanitizeAndLimitForLog(responseBody) ?? "<empty>");
        }

        // Rebuild content so callers can read response body.
        var restoredContent = new StringContent(responseBody, Encoding.UTF8);
        if (response.Content.Headers.ContentType is not null)
            restoredContent.Headers.ContentType = response.Content.Headers.ContentType;

        foreach (var header in response.Content.Headers)
        {
            if (string.Equals(header.Key, "Content-Type", StringComparison.OrdinalIgnoreCase))
                continue;
            restoredContent.Headers.TryAddWithoutValidation(header.Key, header.Value);
        }

        response.Content = restoredContent;
        return response;
    }

    private async Task<HttpResponseMessage> SendBinaryWithLoggingAsync(HttpRequestMessage request)
    {
        _logger.LogInformation(
            "Gramps API binary request: {Method} {Path}",
            request.Method.Method,
            PathForLog(request.RequestUri));

        var startedAt = DateTime.UtcNow;
        var response = await _httpClient.SendAsync(request, HttpCompletionOption.ResponseHeadersRead);
        var elapsedMs = (DateTime.UtcNow - startedAt).TotalMilliseconds;

        _logger.LogInformation(
            "Gramps API binary response: {Method} {Path} Status={StatusCode} DurationMs={DurationMs} ContentType={ContentType} ContentLength={ContentLength}",
            request.Method.Method,
            PathForLog(request.RequestUri),
            (int)response.StatusCode,
            elapsedMs,
            response.Content.Headers.ContentType?.ToString() ?? "<unknown>",
            response.Content.Headers.ContentLength?.ToString() ?? "<unknown>");

        return response;
    }

    private static async Task<byte[]> ReadBytesWithLimitAsync(HttpContent content, long maxBytes)
    {
        await using var stream = await content.ReadAsStreamAsync();
        using var output = new MemoryStream();
        var buffer = new byte[81920];
        long total = 0;

        while (true)
        {
            var read = await stream.ReadAsync(buffer);
            if (read == 0)
                break;

            total += read;
            if (total > maxBytes)
                throw MediaSizeLimitExceeded(total, maxBytes);

            output.Write(buffer, 0, read);
        }

        return output.ToArray();
    }

    private static InvalidOperationException MediaSizeLimitExceeded(long actualBytes, long maxBytes)
    {
        return new InvalidOperationException(
            $"Media response is {actualBytes} bytes, exceeding the configured limit of {maxBytes} bytes.");
    }

    /// <summary>
    /// Path without host or query string; queries carry search terms and filters.
    /// </summary>
    private static string PathForLog(Uri? uri)
    {
        if (uri is null)
            return string.Empty;

        return uri.IsAbsoluteUri
            ? uri.AbsolutePath
            : uri.OriginalString.Split('?', 2)[0];
    }

    private static string? SanitizeAndLimitForLog(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return value;

        var sanitized = RedactSensitiveData(value);
        const int maxLength = 2000;
        return sanitized.Length <= maxLength
            ? sanitized
            : $"{sanitized[..maxLength]}...(truncated)";
    }

    private static string RedactSensitiveData(string input)
    {
        try
        {
            var node = JsonNode.Parse(input);
            if (node is null)
                return input;

            RedactNode(node);
            return node.ToJsonString();
        }
        catch (JsonException)
        {
            // Keep non-JSON payloads readable in logs.
            return input;
        }
    }

    private static void RedactNode(JsonNode node, string? propertyName = null)
    {
        if (!string.IsNullOrWhiteSpace(propertyName) && IsSensitiveField(propertyName))
        {
            if (node is JsonValue)
            {
                node.ReplaceWith(JsonValue.Create("***redacted***"));
            }
            else
            {
                // Entire subtree contains sensitive value.
                node.ReplaceWith(JsonValue.Create("***redacted***"));
            }
            return;
        }

        if (node is JsonObject obj)
        {
            foreach (var kvp in obj.ToList())
            {
                if (kvp.Value is not null)
                    RedactNode(kvp.Value, kvp.Key);
            }
            return;
        }

        if (node is JsonArray array)
        {
            foreach (var item in array)
            {
                if (item is not null)
                    RedactNode(item, propertyName);
            }
        }
    }

    private static bool IsSensitiveField(string key)
    {
        var lowered = key.ToLowerInvariant();
        return SensitiveFieldNames.Any(lowered.Contains);
    }

    private static int? GetIntQuery(string path, string key)
    {
        var idx = path.IndexOf('?', StringComparison.Ordinal);
        if (idx < 0 || idx >= path.Length - 1)
            return null;

        var query = path[(idx + 1)..];
        foreach (var segment in query.Split('&', StringSplitOptions.RemoveEmptyEntries))
        {
            var kv = segment.Split('=', 2);
            if (kv.Length != 2)
                continue;
            if (!string.Equals(Uri.UnescapeDataString(kv[0]), key, StringComparison.OrdinalIgnoreCase))
                continue;
            if (int.TryParse(Uri.UnescapeDataString(kv[1]), out var val))
                return val;
        }

        return null;
    }

    private static int? TryGetTotalFromHeaders(
        System.Net.Http.Headers.HttpResponseHeaders headers,
        System.Net.Http.Headers.HttpContentHeaders contentHeaders)
    {
        // Common conventions used by REST APIs.
        var candidates = new[] { "X-Total-Count", "X-Total", "Total-Count" };
        foreach (var name in candidates)
        {
            if (headers.TryGetValues(name, out var vals) &&
                int.TryParse(vals.FirstOrDefault(), out var total))
                return total;
            if (contentHeaders.TryGetValues(name, out vals) &&
                int.TryParse(vals.FirstOrDefault(), out total))
                return total;
        }

        // Content-Range format: "items start-end/total" or "start-end/total"
        if (headers.TryGetValues("Content-Range", out var ranges) || contentHeaders.TryGetValues("Content-Range", out ranges))
        {
            var v = ranges.FirstOrDefault();
            if (!string.IsNullOrEmpty(v))
            {
                var slash = v.LastIndexOf('/');
                if (slash >= 0 && slash < v.Length - 1 &&
                    int.TryParse(v[(slash + 1)..].Trim(), out var total))
                    return total;
            }
        }

        return null;
    }

}
